func TestRecomposedAncestorWriteCarriesTheTombstoneAndLockPredicates(t *testing.T) {
	db, mock, _ := sqlmock.New(sqlmock.QueryMatcherOption(captureSQLMatcher{queries: &queries}))
	mock.ExpectExec(".*").WillReturnResult(sqlmock.NewResult(0, 1))
	writeRecomposedAncestor(context.Background(), db, uuid.New(), "<article>x</article>")
	whereAt := strings.Index(queries[0], "WHERE")
	for _, p := range []string{"build_status IS DISTINCT FROM 'removed'", "locked_at IS NULL"} {
		if at := strings.Index(queries[0], p); at < 0 || at < whereAt {
			t.Errorf("missing or non-enforcing predicate %q", p)
		}
	}
}

func TestRecomposeAncestorsIsInertOnATopLevelRow(t *testing.T) {
	mock.ExpectQuery("parent_instance_id").WithArgs(child).
		WillReturnRows(sqlmock.NewRows([]string{"parent_instance_id"}).AddRow(nil))
	stale := recomposeAncestors(context.Background(), ActionParams{DB: db}, db, child, uuid.New(), zap.NewNop())
	if len(stale) != 0 { t.Errorf("got %v", stale) }
	if err := mock.ExpectationsWereMet(); err != nil { t.Errorf("%v", err) }
}
